    const summary=root.querySelector('.exportSummary'),cfg=state.project.studio_config.render,clipEnd=cfg.end??state.media.duration,extension=cfg.dubbed?Math.max(0,...state.project.segments.filter(s=>localStatus(s)==='ready'&&s.start<clipEnd&&s.end>cfg.start).map(s=>(audioEntries[s.id].play_end-clipEnd)/cfg.speed)):0;if(summary)summary.textContent=`${state.filepath.split('/').pop()} · ${count} câu · ${cfg.subtitles?'Có phụ đề':'Tắt phụ đề'} · ${cfg.dubbed?'Dùng lồng tiếng':'Giữ âm thanh gốc'}${extension>.05?' · Giữ hình cuối thêm '+extension.toFixed(1)+' giây':''}${cfg.subtitles&&missing?' · '+missing+' câu dùng chữ gốc vì chưa dịch':''}`;
