  function draw(){if(!canvas||!state)return;const width=Math.max(600,canvas.parentElement.clientWidth),height=130;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#10192c';ctx.fillRect(0,0,width,height);ctx.strokeStyle='#536a9a';ctx.beginPath();peaks.forEach((p,i)=>{const x=i/peaks.length*width;ctx.moveTo(x,35-p*28);ctx.lineTo(x,35+p*28);});ctx.stroke();const duration=state.media.duration;state.project.segments.forEach((s,i)=>{const x=s.start/duration*width,w=(s.end-s.start)/duration*width;ctx.fillStyle=s.start<=video.currentTime&&s.end>video.currentTime?'#818cf8':'#334b76';ctx.fillRect(x,76,Math.max(2,w),32);ctx.fillStyle='white';ctx.fillText(String(i+1),x+4,96);ctx.fillStyle='#c7d2fe';ctx.fillRect(x,76,3,32);ctx.fillRect(x+w-3,76,3,32);});ctx.fillStyle='#a7b2cd';ctx.font='12px StudioSans';for(let i=0;i<=6;i++){const x=i/6*width;ctx.fillText((duration*i/6).toFixed(1)+'s',Math.min(x+3,width-48),123);}ctx.fillStyle='#fbbf24';ctx.fillRect(video.currentTime/duration*width,0,2,height);}
