    const tabs=el('nav',undefined,'workflowTabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Quy trình làm video');steps.forEach(([key,name],index)=>{const tab=button(`${index+1}. ${name}`,()=>setStep(key));tab.dataset.step=key;tab.id='studio-tab-'+key;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','studio-panel-'+key);tab.setAttribute('aria-selected',String(propertyTab===key));tab.tabIndex=propertyTab===key?0:-1;tab.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();setStep(steps[e.key==='Home'?0:e.key==='End'?3:(index+(e.key==='ArrowRight'?1:3))%4][0],true);};tabs.append(tab);});root.append(tabs);
    notice=el('div',undefined,'notice');notice.setAttribute('role','status');root.append(notice);const layout=el('div',undefined,'layout');
