    const jobs=await api('/jobs?'+new URLSearchParams({filepath}));if(!root||token!==session)return;await refreshJobs(jobs.jobs);const pending=jobs.jobs.find(j=>!terminal(j));if(pending){busy=true;poll(pending,token).catch(e=>message(e.message,true));}else if(jobs.jobs[0])showJob(jobs.jobs[0]);const previousWave=jobs.jobs.find(j=>j.kind==='waveform'&&j.status==='completed'&&j.peaks);if(previousWave){peaks=previousWave.peaks;draw();}renderActions();
