  function close(){++session;if(jobTimer)clearTimeout(jobTimer);if(audioPlayer)audioPlayer.pause();if(video)video.pause();root?._headerSizer?.disconnect();root?.remove();root=null;document.body.style.overflow='';busy=false;}
